questionvariables.text:
/* Linear scale factor p/q in lowest terms, p > q */
qden : rand(3) + 2;
pnum : qden + rand(3) + 1;
g : gcd(pnum, qden);
pnum : pnum / g;
qden : qden / g;

/* Base multiplier so both areas come out as whole numbers */
m : rand(4) + 2;
area_small : m * qden^2;
area_large : m * pnum^2;

/* Given side length of the smaller pentagon, cm */
a : rand(6) + 4;

/* Correct answer: corresponding side length of the larger pentagon */
ta : decimalplaces(a*pnum/qden, 2);

/* mistakes */
/* Used the area ratio directly on the side length, without a square root */
ta1 : decimalplaces(a*area_large/area_small, 2);
/* Found the smaller pentagon's side instead of the larger one (used the reciprocal ratio) */
ta2 : decimalplaces(a*qden/pnum, 2);
